    <Reveal><section className="section section-light"><div className="container"><SectionLabel>WHO WE SERVE</SectionLabel><div className="section-heading"><h2>Partnerships built on delivery.</h2><p>From aviation to food production, organizations rely on us for dependable engineering and supply support.</p></div><div className="logos-row">{clients.map(c=><div className="logo-chip" key={c.n} title={c.n}><span className="logo-mono">{c.mono}</span><img src={c.lg} alt={`${c.n} logo`} onError={e=>{e.currentTarget.style.display='none'}}/></div>)}</div><div className="clients-grid">{clients.map((c,i)=><div className="client-card" key={c.n} data-testid={`client-${i}`}><c.icon size={26}/><span className="client-ind">{c.ind}</span><h3>{c.n}</h3><p>{c.d}</p></div>)}</div></div></section></Reveal>
